/* ---------- scan ---------- */
let SCAN={stream:null,timer:null,last:'',lastT:0,on:null};
async function startScan(onRaw){
  const v=$('#vid'),log=$('#scanlog');stopScan();SCAN.on=onRaw||handleRaw;
  try{SCAN.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280}}})}catch(e){log.textContent='Caméra refusée ou indisponible : utilise « Photo d’un QR » ou colle le texte.';return}
  v.srcObject=SCAN.stream;await v.play();v.classList.add('on');
  const det='BarcodeDetector' in window?new BarcodeDetector({formats:['qr_code']}):null;const cv=$('#cv'),ctx=cv.getContext('2d',{willReadFrequently:true});
  log.textContent='Vise un QR code…';
  SCAN.timer=setInterval(async()=>{if(!v.videoWidth)return;let raw=null;
    try{if(det){const c=await det.detect(v);if(c.length)raw=c[0].rawValue}else{const w=Math.min(960,v.videoWidth),h=R(v.videoHeight*w/v.videoWidth);cv.width=w;cv.height=h;ctx.drawImage(v,0,0,w,h);const img=ctx.getImageData(0,0,w,h);const c=jsQR(img.data,w,h,{inversionAttempts:'dontInvert'});if(c)raw=c.data}}catch(e){}
    if(!raw)return;const now=Date.now();if(raw===SCAN.last&&now-SCAN.lastT<4000)return;SCAN.last=raw;SCAN.lastT=now;(SCAN.on||handleRaw)(raw)},250);
}
function stopScan(){if(SCAN.timer)clearInterval(SCAN.timer);SCAN.timer=null;if(SCAN.stream)SCAN.stream.getTracks().forEach(t=>t.stop());SCAN.stream=null;const v=$('#vid');if(v){v.srcObject=null;v.classList.remove('on')}}
function handleRaw(raw){const log=$('#scanlog');try{raw=decodeUtf8(raw);const res=profAddAny(raw);if(res&&res.partial){if(log)log.innerHTML='… '+esc(res.partial)+'<br>'+(log.innerHTML||'');return}const msg=res;beep();if(log)log.innerHTML='✓ '+esc(msg)+'<br>'+(log.innerHTML||'');toast('✓ '+msg)}catch(e){if(log)log.innerHTML='✗ '+esc(e.message)+'<br>'+log.innerHTML}}
function decodeUtf8(s){try{return /Ã|Â/.test(s)?decodeURIComponent(escape(s)):s}catch(e){return s}}
let AC=null;
function beep(f,ms){try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();const o=AC.createOscillator(),g=AC.createGain();o.frequency.value=f||880;g.gain.value=.25;o.connect(g);g.connect(AC.destination);o.start();o.stop(AC.currentTime+(ms||150)/1000)}catch(e){}}
function decodePhoto(file){const r=new FileReader();r.onload=e=>{const img=new Image();img.onload=()=>{const cv=$('#cv'),ctx=cv.getContext('2d');const sc=Math.min(1,1600/Math.max(img.width,img.height));cv.width=R(img.width*sc);cv.height=R(img.height*sc);ctx.drawImage(img,0,0,cv.width,cv.height);const d=ctx.getImageData(0,0,cv.width,cv.height);const c=jsQR(d.data,cv.width,cv.height);if(c)handleRaw(c.data);else $('#scanlog').textContent='QR non reconnu : photo plus nette, bien cadrée.'};img.src=e.target.result};r.readAsDataURL(file)}

